        => _scope.InvokeAsync<ToolInvocationRequest, AgentRpcOptionalOfAgentToolResult>(_endpoint, "tool-source", "preflight", request, cancellationToken: cancellationToken);

    public ValueTask<AgentRpcOptionalOfAgentToolPresentation> PresentationAsync(AgentToolPresentationRequest request, CancellationToken cancellationToken = default)
        => _scope.InvokeAsync<AgentToolPresentationRequest, AgentRpcOptionalOfAgentToolPresentation>(_endpoint, "tool-source", "presentation", request, cancellationToken: cancellationToken);

}

public sealed class SunderAgentToolSourceRpcHandler : ISunderRpcServiceHandler
{
    private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web)
    {
        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
        PropertyNameCaseInsensitive = false,
        UnmappedMemberHandling = JsonUnmappedMemberHandling.Disallow,
    };
    private readonly IToolSourceProvider _service1;

    public SunderAgentToolSourceRpcHandler(IToolSourceProvider service1)
    {
        _service1 = service1 ?? throw new ArgumentNullException(nameof(service1));
    }

    public ValueTask<JsonElement> InvokeUnaryAsync(
        SunderRpcInvocationContext context,
        string serviceId,
        string methodId,
        JsonElement request,
        CancellationToken cancellationToken = default)
    {
        if (string.Equals(serviceId, "tool-source", StringComparison.Ordinal) && string.Equals(methodId, "describe", StringComparison.Ordinal))
        {
            return SerializeUnaryAsync(_service1.DescribeAsync(context, Deserialize<AgentRpcEmpty>(request), cancellationToken));
        }
        if (string.Equals(serviceId, "tool-source", StringComparison.Ordinal) && string.Equals(methodId, "execute", StringComparison.Ordinal))
        {
            return SerializeUnaryAsync(_service1.ExecuteAsync(context, Deserialize<ToolInvocationRequest>(request), cancellationToken));
        }
        if (string.Equals(serviceId, "tool-source", StringComparison.Ordinal) && string.Equals(methodId, "get-readiness", StringComparison.Ordinal))
        {
            return SerializeUnaryAsync(_service1.GetReadinessAsync(context, Deserialize<ToolReadinessRequest>(request), cancellationToken));
        }
        if (string.Equals(serviceId, "tool-source", StringComparison.Ordinal) && string.Equals(methodId, "list-tools", StringComparison.Ordinal))
        {
            return SerializeUnaryAsync(_service1.ListToolsAsync(context, Deserialize<AgentToolSourceContextWire>(request), cancellationToken));
        }
        if (string.Equals(serviceId, "tool-source", StringComparison.Ordinal) && string.Equals(methodId, "permission", StringComparison.Ordinal))
        {
            return SerializeUnaryAsync(_service1.PermissionAsync(context, Deserialize<ToolInvocationRequest>(request), cancellationToken));
        }
        if (string.Equals(serviceId, "tool-source", StringComparison.Ordinal) && string.Equals(methodId, "preflight", StringComparison.Ordinal))
        {
            return SerializeUnaryAsync(_service1.PreflightAsync(context, Deserialize<ToolInvocationRequest>(request), cancellationToken));
        }
        if (string.Equals(serviceId, "tool-source", StringComparison.Ordinal) && string.Equals(methodId, "presentation", StringComparison.Ordinal))
        {
            return SerializeUnaryAsync(_service1.PresentationAsync(context, Deserialize<AgentToolPresentationRequest>(request), cancellationToken));
        }
        return ValueTask.FromException<JsonElement>(UnknownMethod(serviceId, methodId, "unary"));
    }

    public IAsyncEnumerable<JsonElement> InvokeServerStreamAsync(
        SunderRpcInvocationContext context,
        string serviceId,
        string methodId,
        JsonElement request,
        CancellationToken cancellationToken = default)
    {
        return ThrowStream(UnknownMethod(serviceId, methodId, "server-stream"), cancellationToken);
    }

    private static async ValueTask<JsonElement> SerializeUnaryAsync<T>(ValueTask<T> response)
        where T : notnull
        => JsonSerializer.SerializeToElement(await response.ConfigureAwait(false), JsonOptions);

    private static T Deserialize<T>(JsonElement value)
        where T : notnull
        => value.Deserialize<T>(JsonOptions)
           ?? throw new InvalidOperationException("A validated RPC request deserialized to null.");

    private static async IAsyncEnumerable<JsonElement> SerializeStream<T>(
        IAsyncEnumerable<T> source,
        [EnumeratorCancellation] CancellationToken cancellationToken)
        where T : notnull
    {
        await foreach (var item in source.WithCancellation(cancellationToken).ConfigureAwait(false))
        {
            yield return JsonSerializer.SerializeToElement(item, JsonOptions);
        }
    }

    private static async IAsyncEnumerable<JsonElement> ThrowStream(
        Exception exception,
        [EnumeratorCancellation] CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();
        await Task.CompletedTask;
        throw exception;
#pragma warning disable CS0162
        yield break;
#pragma warning restore CS0162
    }

    private static Exception UnknownMethod(string serviceId, string methodId, string kind)
        => new InvalidOperationException($"RPC provider adapter does not implement {kind} method '{serviceId}/{methodId}'.");
}

